const MODELE_SNAKE_B64 = "";

function getModeleArrayBuffer() {
  const bin = atob(MODELE_SNAKE_B64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

function getModeleSizeKB() {
  return Math.round(MODELE_SNAKE_B64.length * 0.75 / 1024);
}
